using System;using System.IO;using System.Linq;using System.Reflection;using System.Text;using System.Collections.Generic;using System.Diagnostics;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioVertexMarkerValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static StringBuilder log=new StringBuilder();static int checks;static bool occlude;static Mesh depthPlane;static Material depthMaterial;
 static object Get(object o,string n)=>o.GetType().GetField(n,F).GetValue(o);static void Set(object o,string n,object v)=>o.GetType().GetField(n,F).SetValue(o,v);static void Call(object o,string n,params object[] a)=>o.GetType().GetMethod(n,F).Invoke(o,a);
 static void Check(bool ok,string m){if(!ok)throw new Exception(m);checks++;}
 static Mesh Cloud(int count){var m=new Mesh{indexFormat=IndexFormat.UInt32};var p=new Vector3[count];int side=(int)Math.Ceiling(Math.Sqrt(count));for(int i=0;i<count;i++)p[i]=new Vector3((i%side)/(float)side*1.6f-.8f,(i/side)/(float)side*1.6f-.8f,0);m.vertices=p;m.triangles=new[]{0,1,side};m.RecalculateBounds();return m;}
 static Color32[] Render(StudioModelEditor ed,SceneView view,RenderTexture rt){var old=RenderTexture.active;RenderTexture.active=rt;GL.PushMatrix();try{GL.Clear(true,true,Color.black);GL.LoadProjectionMatrix(view.camera.projectionMatrix);GL.modelview=view.camera.worldToCameraMatrix;if(occlude){depthMaterial.SetPass(0);Graphics.DrawMeshNow(depthPlane,Matrix4x4.TRS(new Vector3(0,0,-.2f),Quaternion.identity,Vector3.one*5));}Call(ed,"DrawComponentBatches",view);var t=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);try{t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();return t.GetPixels32();}finally{Object.DestroyImmediate(t);}}finally{GL.PopMatrix();RenderTexture.active=old;}}
 static void Correctness(){var doc=ScriptableObject.CreateInstance<StudioModelDocument>();var mesh=Cloud(64);doc.nodes.Add(new StudioModelDocument.Node{name="Marker test",mesh=mesh});var view=ScriptableObject.CreateInstance<SceneView>();var rt=new RenderTexture(256,256,24);rt.Create();view.camera.targetTexture=rt;view.camera.orthographic=true;view.camera.orthographicSize=1;view.camera.transform.position=new Vector3(0,0,-3);view.camera.transform.rotation=Quaternion.identity;
 using(var ed=new StudioModelEditor(()=>{})){ed.Load(doc);ed.SelectObject(0);Set(ed,"mode",StudioModelEditor.ComponentMode.Vertex);ed.Components.Add(3);ed.Components.Add(20);Set(ed,"hoveredComponent",10);
 foreach(bool xray in new[]{false,true})foreach(bool ortho in new[]{false,true}){Set(ed,"displayXray",xray);view.camera.orthographic=ortho;
 ed.ForceLegacyVertexMarkers=true;Call(ed,"ClearComponentDrawing");var reference=Render(ed,view,rt);Check(reference.Count(c=>c.g>30)>50,"Legacy markers visible");
 ed.ForceLegacyVertexMarkers=false;Call(ed,"ClearComponentDrawing");var gpu=Render(ed,view,rt);int difference=reference.Zip(gpu,(a,b)=>a.Equals(b)?0:1).Sum();log.AppendLine("Render ortho="+ortho+" xray="+xray+" different pixels="+difference);if(difference!=0){foreach(var pair in new[]{("reference",reference),("gpu",gpu)}){var image=new Texture2D(256,256,TextureFormat.RGBA32,false);image.SetPixels32(pair.Item2);image.Apply();File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../marker-"+pair.Item1+".png")),image.EncodeToPNG());Object.DestroyImmediate(image);}log.AppendLine("Pixels reference="+reference.Count(c=>c.g>30)+" GPU="+gpu.Count(c=>c.g>30));}Check(difference==0,"GPU pixels differ from cached-quad reference");Check(Get(ed,"componentDots")==null&&Get(ed,"componentHighlight")==null&&Get(ed,"componentHover")==null,"GPU path builds no marker meshes");
 }
 depthPlane=StudioModelDocument.BuildPrimitive(PrimitiveType.Quad);depthMaterial=new Material(Shader.Find("Hidden/StudioValidationSolid"));occlude=true;Set(ed,"displayXray",false);var hidden=Render(ed,view,rt);Set(ed,"displayXray",true);var visible=Render(ed,view,rt);Check(hidden.Count(c=>c.g>c.r+30&&c.b>c.r+30)==0,"Depth plane occludes GPU markers");Check(visible.Count(c=>c.g>c.r+30&&c.b>c.r+30)>50,"X-ray draws markers through depth plane");occlude=false;Object.DestroyImmediate(depthPlane);Object.DestroyImmediate(depthMaterial);var positions=(GraphicsBuffer)Get(ed,"markerPositions");var selection=(GraphicsBuffer)Get(ed,"markerSelection");long bytes=ed.VertexMarkerUploadBytes;int uploads=ed.VertexMarkerSelectionUploads;for(int i=0;i<10;i++)Call(ed,"EnsureComponentDrawing");Check(ReferenceEquals(positions,Get(ed,"markerPositions"))&&bytes==ed.VertexMarkerUploadBytes&&uploads==ed.VertexMarkerSelectionUploads,"Idle reuses buffers without uploads");
 ed.Components.Clear();ed.Components.UnionWith(new[]{1,4});Call(ed,"EnsureComponentDrawing");Check(ReferenceEquals(selection,Get(ed,"markerSelection")),"Selection capacity reused");
 var source=mesh.vertices;var sourcePixels=Render(ed,view,rt);var next=(Vector3[])source.Clone();next[1]+=Vector3.right*.1f;next[50]+=Vector3.up*.1f;bytes=ed.VertexMarkerUploadBytes;Call(ed,"RefreshComponentPositions",0,next,new[]{1,50});Check(ed.VertexMarkerUploadBytes-bytes==24,"Two sparse points upload exactly 24 bytes");var read=new Vector3[source.Length];positions.GetData(read);for(int i=0;i<read.Length;i++)Check(read[i].Equals(next[i]),"GPU sparse position readback");
 Check(!Render(ed,view,rt).SequenceEqual(sourcePixels),"Sparse update changes rendered markers");Call(ed,"RefreshComponentPositions",0,source,null);positions.GetData(read);Check(read.SequenceEqual(source),"Reversal restores original GPU positions");Check(Render(ed,view,rt).SequenceEqual(sourcePixels),"Reversal restores rendered markers");
 bytes=ed.VertexMarkerUploadBytes;Call(ed,"RefreshComponentPositions",0,source,null);Check(bytes==ed.VertexMarkerUploadBytes,"Unchanged positions do not upload");
 ed.Components.UnionWith(Enumerable.Range(0,64));Call(ed,"EnsureComponentDrawing");var grown=Get(ed,"markerSelection");Check(!ReferenceEquals(selection,grown),"Selection buffer grows when required");ed.Components.Clear();ed.Components.Add(2);Call(ed,"EnsureComponentDrawing");Check(ReferenceEquals(grown,Get(ed,"markerSelection")),"Selection buffer retains grown capacity");
 Call(ed,"ClearComponentDrawing");Check(Get(ed,"markerPositions")==null&&Get(ed,"markerSelection")==null,"Reset releases buffers");Call(ed,"EnsureComponentDrawing");Check(Get(ed,"markerPositions")!=null&&!ReferenceEquals(positions,Get(ed,"markerPositions")),"Reset rebuilds from authoritative mesh");
 }
 view.camera.targetTexture=null;Object.DestroyImmediate(view);Object.DestroyImmediate(rt);Object.DestroyImmediate(mesh);Object.DestroyImmediate(doc);}
 static void Performance(){foreach(int n in new[]{16384,262144,1000000}){var doc=ScriptableObject.CreateInstance<StudioModelDocument>();var mesh=Cloud(n);doc.nodes.Add(new StudioModelDocument.Node{name="Marker benchmark",mesh=mesh});using(var ed=new StudioModelEditor(()=>{})){ed.Load(doc);ed.SelectObject(0);Set(ed,"mode",StudioModelEditor.ComponentMode.Vertex);var source=mesh.vertices;var moving=new[]{0,1,2,3,4,5,6,7};var next=(Vector3[])source.Clone();
 foreach(bool dense in new[]{false,true})foreach(bool legacy in n==1000000?new[]{false}:new[]{true,false}){ed.ForceLegacyVertexMarkers=legacy;Call(ed,"ClearComponentDrawing");Call(ed,"EnsureComponentDrawing");var updatePoints=dense?Enumerable.Range(0,n/2).ToArray():moving;var refresh=(Action<int,IList<Vector3>,int[]>)typeof(StudioModelEditor).GetMethod("RefreshComponentPositions",F).CreateDelegate(typeof(Action<int,IList<Vector3>,int[]>),ed);var samples=new double[50];for(int i=-10;i<50;i++){foreach(int p in updatePoints)next[p]=source[p]+Vector3.right*(.01f+(i+10)*.001f);var watch=Stopwatch.StartNew();refresh(0,next,updatePoints);watch.Stop();if(i>=0)samples[i]=watch.Elapsed.TotalMilliseconds;}if(!legacy){var verify=new Vector3[n];((GraphicsBuffer)Get(ed,"markerPositions")).GetData(verify);Check(verify.SequenceEqual(next),"Benchmark updated every requested GPU point");}Array.Sort(samples);log.AppendLine("PERF markers="+n+" legacy="+legacy+" points="+updatePoints.Length+" update median_ms="+samples[25].ToString("F4")+" p95_ms="+samples[47].ToString("F4"));}
 }Object.DestroyImmediate(mesh);Object.DestroyImmediate(doc);}}
 public static void Run(){int exit=0;try{Check(Shader.Find("Hidden/MashBox/ModelerVertexMarkers")&&Shader.Find("Hidden/MashBox/ModelerVertexMarkers").isSupported,"GPU shader supported");Correctness();Performance();File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../vertex-marker-result.txt")),log.ToString());StudioVertexMarkerMoveValidation.Validate();log.AppendLine("PASS "+checks+" marker assertions; Move regression also passed");}catch(Exception e){exit=1;log.AppendLine(e.ToString());}File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../vertex-marker-result.txt")),log.ToString());EditorApplication.Exit(exit);}
}